{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "hero_card",
        "film_selection_title",
        "film_table",
        "movie_details_header_stack",
        "movie_details_stack",
        "schedule_title",
        "schedule_table",
        "actions_title",
        "actions_stack",
        "sources_title",
        "sources_stack"
      ]
    },
    "hero_card": {
      "type": "Card",
      "props": {},
      "children": [
        "hero_image",
        "hero_title_stack",
        "hero_description"
      ]
    },
    "hero_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/London_Eye_at_Night.jpg/1200px-London_Eye_at_Night.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "hero_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "hero_title",
        "hero_icon"
      ]
    },
    "hero_title": {
      "type": "Text",
      "props": {
        "text": "90s Psychological Thriller Marathon",
        "variant": "h1"
      },
      "children": []
    },
    "hero_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/moon-stars.svg"
      },
      "children": []
    },
    "hero_description": {
      "type": "Text",
      "props": {
        "text": "This 6-hour marathon features the peak of 1990s suspense. We have selected three critically acclaimed thrillers that define the genre's dark and cerebral atmosphere.",
        "variant": "body"
      },
      "children": []
    },
    "film_selection_title": {
      "type": "Text",
      "props": {
        "text": "Film Selection and Pairings",
        "variant": "h2"
      },
      "children": []
    },
    "film_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "title",
            "label": "Title"
          },
          {
            "key": "year",
            "label": "Year"
          },
          {
            "key": "actors",
            "label": "Lead Actors"
          },
          {
            "key": "tension",
            "label": "Tension"
          }
        ],
        "rows": [
          {
            "title": "The Silence of the Lambs",
            "year": "1991",
            "actors": "Jodie Foster, Anthony Hopkins",
            "tension": "10/10"
          },
          {
            "title": "Se7en",
            "year": "1995",
            "actors": "Brad Pitt, Morgan Freeman",
            "tension": "9/10"
          },
          {
            "title": "The Sixth Sense",
            "year": "1999",
            "actors": "Bruce Willis, Haley Joel Osment",
            "tension": "8/10"
          }
        ],
        "domain": "generic",
        "preferredPresentation": "cards",
        "primaryColumn": "title",
        "highlightColumns": [
          "tension"
        ]
      },
      "children": []
    },
    "movie_details_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "movie_details_icon",
        "movie_details_title"
      ]
    },
    "movie_details_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/ticket-perforated.svg"
      },
      "children": []
    },
    "movie_details_title": {
      "type": "Text",
      "props": {
        "text": "Curated Movie Details",
        "variant": "h2"
      },
      "children": []
    },
    "movie_details_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "silence_card",
        "se7en_card",
        "sixth_sense_card"
      ]
    },
    "silence_card": {
      "type": "Card",
      "props": {},
      "children": [
        "silence_title",
        "silence_description"
      ]
    },
    "silence_title": {
      "type": "Text",
      "props": {
        "text": "The Silence of the Lambs (1991)",
        "variant": "h3"
      },
      "children": []
    },
    "silence_description": {
      "type": "Text",
      "props": {
        "text": "A young FBI cadet must receive the help of an incarcerated cannibal to catch another serial killer. Pairing: Chianti wine and fava bean crostini.",
        "variant": "body"
      },
      "children": []
    },
    "se7en_card": {
      "type": "Card",
      "props": {},
      "children": [
        "se7en_title",
        "se7en_description"
      ]
    },
    "se7en_title": {
      "type": "Text",
      "props": {
        "text": "Se7en (1995)",
        "variant": "h3"
      },
      "children": []
    },
    "se7en_description": {
      "type": "Text",
      "props": {
        "text": "Two detectives hunt a serial killer who uses the seven deadly sins as his motifs. Pairing: A dark stout beer and \"Gluttony\" charcuterie board.",
        "variant": "body"
      },
      "children": []
    },
    "sixth_sense_card": {
      "type": "Card",
      "props": {},
      "children": [
        "sixth_sense_title",
        "sixth_sense_description"
      ]
    },
    "sixth_sense_title": {
      "type": "Text",
      "props": {
        "text": "The Sixth Sense (1999)",
        "variant": "h3"
      },
      "children": []
    },
    "sixth_sense_description": {
      "type": "Text",
      "props": {
        "text": "A child psychologist treats a young boy who claims to see dead people. Pairing: Hot cocoa with \"Red\" velvet cupcakes.",
        "variant": "body"
      },
      "children": []
    },
    "schedule_title": {
      "type": "Text",
      "props": {
        "text": "Marathon Schedule (6:00 PM - 12:13 AM EST)",
        "variant": "h2"
      },
      "children": []
    },
    "schedule_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "time",
            "label": "Time"
          },
          {
            "key": "event",
            "label": "Event"
          },
          {
            "key": "duration",
            "label": "Duration"
          }
        ],
        "rows": [
          {
            "time": "18:00",
            "event": "The Silence of the Lambs",
            "duration": "118 mins"
          },
          {
            "time": "19:58",
            "event": "Intermission 1",
            "duration": "15-minute break for discussion and appetizer refills"
          },
          {
            "time": "20:13",
            "event": "Se7en",
            "duration": "127 mins"
          },
          {
            "time": "22:20",
            "event": "Intermission 2",
            "duration": "15-minute break to prepare for the final feature"
          },
          {
            "time": "22:35",
            "event": "The Sixth Sense",
            "duration": "107 mins"
          },
          {
            "time": "00:22",
            "event": "Conclusion",
            "duration": ""
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "time",
        "highlightColumns": [
          "event"
        ]
      },
      "children": []
    },
    "actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "imdb_button",
        "justwatch_button"
      ]
    },
    "imdb_button": {
      "type": "Button",
      "props": {
        "label": "View IMDb Details"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.imdb.com"
          }
        }
      },
      "children": []
    },
    "justwatch_button": {
      "type": "Button",
      "props": {
        "label": "Streaming Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.justwatch.com"
          }
        }
      },
      "children": []
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "imdb_source_button",
        "rt_source_button"
      ]
    },
    "imdb_source_button": {
      "type": "Button",
      "props": {
        "label": "IMDb Movie Ratings",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.imdb.com"
          }
        }
      },
      "children": []
    },
    "rt_source_button": {
      "type": "Button",
      "props": {
        "label": "Rotten Tomatoes",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.rottentomatoes.com"
          }
        }
      },
      "children": []
    }
  }
}
